CREATE FUNCTION enforce_session_epoch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."sessionEpoch" := GREATEST(COALESCE(NEW."sessionEpoch", 1), 1);
  ELSE
    IF NEW."sessionEpoch" IS NULL OR NEW."sessionEpoch" < OLD."sessionEpoch" THEN
      RAISE EXCEPTION 'Session epoch cannot decrease' USING ERRCODE = '23514';
    END IF;
    IF ROW(NEW."passwordHash", NEW."openId", NEW.role, NEW.email, NEW."loginMethod")
      IS DISTINCT FROM ROW(OLD."passwordHash", OLD."openId", OLD.role, OLD.email, OLD."loginMethod") THEN
      NEW."sessionEpoch" := GREATEST(NEW."sessionEpoch", OLD."sessionEpoch" + 1);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER users_session_epoch BEFORE INSERT OR UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION enforce_session_epoch();
--> statement-breakpoint
CREATE FUNCTION invalidate_profile_sessions() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE affected integer[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT array_agg(DISTINCT "userId" ORDER BY "userId") INTO affected FROM new_profiles;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT array_agg(DISTINCT "userId" ORDER BY "userId") INTO affected FROM old_profiles;
  ELSE
    SELECT array_agg(DISTINCT uid ORDER BY uid) INTO affected FROM (
      SELECT unnest(ARRAY[o."userId", n."userId"]) AS uid
      FROM old_profiles o FULL JOIN new_profiles n USING (id)
      WHERE ROW(o.id, o."userId", o."founderId", o.status, o."trelloMemberId")
        IS DISTINCT FROM ROW(n.id, n."userId", n."founderId", n.status, n."trelloMemberId")
    ) changed WHERE uid IS NOT NULL;
  END IF;
  -- Lock the complete affected set in stable order, including multi-row writes.
  PERFORM id FROM users WHERE id = ANY(affected) ORDER BY id FOR UPDATE;
  UPDATE users SET "sessionEpoch" = "sessionEpoch" + 1 WHERE id = ANY(affected);
  RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER profile_sessions_insert AFTER INSERT ON va_profiles
REFERENCING NEW TABLE AS new_profiles FOR EACH STATEMENT EXECUTE FUNCTION invalidate_profile_sessions();
--> statement-breakpoint
CREATE TRIGGER profile_sessions_delete AFTER DELETE ON va_profiles
REFERENCING OLD TABLE AS old_profiles FOR EACH STATEMENT EXECUTE FUNCTION invalidate_profile_sessions();
--> statement-breakpoint
CREATE TRIGGER profile_sessions_update AFTER UPDATE ON va_profiles
REFERENCING OLD TABLE AS old_profiles NEW TABLE AS new_profiles
FOR EACH STATEMENT EXECUTE FUNCTION invalidate_profile_sessions();
